// AlLow.java (B) — near-identical logic to CorAl.manualPivotControl (A):
public void manualPivotControl(double stickInput) {
    if (Math.abs(stickInput) >= DEADBAND) {
        positionControlEnabled = false; manualModeEnabled = true;
        pivotMotor.set(Math.min(Math.max(stickInput * SPEED_LIMIT, -1), 1));
    } else if (manualModeEnabled) {
        manualModeEnabled = false;
        holdCurrentAngle();          // capture-and-hold on release
    }
}

private Command moveTo(PresetHeights height, PivotPresetAngles angle) {
    return Commands.defer(() -> planMove(height.getHeight(), angle.getAngle()), Set.of(elevator, coral));
}
private Command settle() {
    return Commands.waitUntil(this::atTargets).withTimeout(SuperstructureConstants.SETTLE_TIMEOUT_SECONDS);
}

public enum PresetHeights {
    BASE(0.0), CORAL_L1(0.0), CORAL_L2(12.0), CORAL_L3(29.0), CORAL_L4(52.5),
    ALGAE_LOW_INTAKE(20.5), ALGAE_HIGH_INTAKE(37.5), ALGAE_SCORE(52.5);
    private final double height;
    PresetHeights(double height) { this.height = height; }
    public double getHeight() { return height; }
}

public Command ejectFirstPiece() {
    return startEnd(() -> rollerMotor.set(KitBotConstants.ROLLER_FIRST_EJECT_VALUE), rollerMotor::stopMotor)
        .withTimeout(KitBotConstants.ROLLER_EJECT_DURATION)
        .withName("EjectFirstPiece");
}

